const schema = JSON.stringify({type:'object',properties:{area:{type:'string'},summary:{type:'string'},confirmed_findings:{type:'array',items:{type:'object',properties:{severity:{type:'string'},title:{type:'string'},evidence:{type:'string'},impact:{type:'string'},reproduction_or_test_gap:{type:'string'},recommendation:{type:'string'}},required:['severity','title','evidence','impact','reproduction_or_test_gap','recommendation']}},intentional_limitations:{type:'array',items:{type:'string'}},tests_inspected:{type:'array',items:{type:'string'}},coverage_gaps:{type:'array',items:{type:'string'}}},required:['area','summary','confirmed_findings','intentional_limitations','tests_inspected','coverage_gaps']});
const work = [
 {area:'Domain, application state, job persistence and architecture',files:'mmnext/domain/**, mmnext/application/**, mmnext/infrastructure/repository/**, tests/test_architecture_gates.py, tests/test_job_repository.py, tests/test_job_service.py, related domain/application tests.'},
 {area:'Transcript production, artifact validation, workers and reopen lifecycle',files:'mmnext/infrastructure/transcript_adapter.py, mmnext/ui/transcript_worker.py, mmnext/ui/reopen_transcript_worker.py, mmnext/ui/app_context.py transcript methods, mmnext/ui/screens/jobs_screen.py, mmnext/ui/main_window.py relevant reopen slots; tests/test_transcript_*.py, tests/test_fingerprint.py, tests/test_live_transcript_workspace.py.'},
 {area:'Exact Dubbing validation, TTS cache and FFmpeg render',files:'mmnext/domain/exact_dubbing.py, mmnext/domain/validation.py, mmnext/application/exact_dubbing_service.py and mode coordinator, mmnext/services/adapters/exact_dubbing_tts.py, mmnext/infrastructure/exact_dubbing_render.py, related UI mode panel; tests/test_exact_dubbing*.py and validation tests.'},
 {area:'Narrator planning, translation/TTS/render pipeline and worker lifecycle',files:'mmnext/application/narrator*.py, mmnext/services/adapters/narrator_*.py, mmnext/ui/narrator_pipeline_worker.py and narrator panel/context slots; tests/test_narrator*.py.'},
 {area:'Splitter and Common Editing planning, rendering and export',files:'mmnext/application/*splitter*.py, mmnext/services/adapters/splitter.py, mmnext/infrastructure/ffmpeg_tools.py, mmnext/infrastructure/*splitter*, common_editing modules and workers; related tests/test_splitter*.py and test_common_editing*.py.'},
 {area:'UI wiring, signal lifecycle, job/source/download/workspace/settings screens',files:'mmnext/ui/** excluding transcript and narrator/exact/splitter code already assigned; focus on signal connections, bound slots, state transitions, demo/real labels, user-triggered destructive changes; related UI tests and architecture gates.'}
];
const mapped = await parallel('Review MMNext code areas read-only', () => work.map((w,i) => agent(
  'Perform a READ-ONLY code review of the current repository J:\\mmnext-movie-recap-pro. Review exactly this area: '+w.area+'. Relevant scope: '+w.files+'\n\nFind concrete defects still present in current source, not merely roadmap limitations. Read current implementations and their tests; cite exact repository-relative file paths and line numbers. Do not edit files, run broad commands, or rely on old checklist claims. Do not report intentional DEMO/unimplemented features as bugs unless code falsely labels them REAL/complete. Check applicable invariants: GUI thread stays responsive; no silent REAL-to-DEMO fallback; atomic/job-scoped persistence; no exact-dubbing source mutation; truthful completion; safe thread/signal lifecycle; architecture direction. Return only structured JSON matching the group schema. For each confirmed finding state severity (Critical/High/Medium/Low), exact evidence, user impact, a minimal test/reproduction gap, and targeted recommendation. Put uncertain items under coverage_gaps, not confirmed_findings. List intentional limitations separately. Do not change source, tests, roadmap, or checklist.',
  {brief:'Кодын '+w.area+' хэсгийг read-only шалгах',schema,sandbox:'shared',effort_level:'standard'}
 )) ,{schema});
const success = mapped.filter(r=>r.ok).map(r=>r.value);
const failures = mapped.map((r,i)=>r.ok?null:{area:work[i].area,code:r.error.code,message:r.error.message}).filter(Boolean);
const reducer = await agent('Synthesize these six independent read-only code-review results for MMNext. Do not invent or upgrade findings. Merge duplicates, preserve exact evidence and distinguish confirmed bugs from risks/intentional limitations. Rank actionable findings by severity and order. Return a concise overall summary plus the structured results and failed workstreams. Inputs:\n'+JSON.stringify({results:success,failures}),{brief:'Зургаан чиглэлийн code audit үр дүнг нэгтгэх',schema:JSON.stringify({type:'object',properties:{overall_summary:{type:'string'},priority_findings:{type:'array',items:{type:'object',properties:{severity:{type:'string'},title:{type:'string'},areas:{type:'array',items:{type:'string'}},evidence:{type:'array',items:{type:'string'}},impact:{type:'string'},recommendation:{type:'string'}},required:['severity','title','areas','evidence','impact','recommendation']}},intentional_limitations:{type:'array',items:{type:'string'}},coverage_gaps:{type:'array',items:{type:'string'}},workstream_failures:{type:'array',items:{type:'string'}}},required:['overall_summary','priority_findings','intentional_limitations','coverage_gaps','workstream_failures']}),sandbox:'shared',effort_level:'standard'});
return {workstreams:success,failures,summary:reducer.ok?reducer.value:null,reducer_failure:reducer.ok?null:reducer.error};

